import heapq
from typing import List

class Solution:
    def smallestRange(self, nums: List[List[int]]) -> List[int]:
        heap = []
        curr_max = float("-inf")
        for i in range(len(nums)):
            heapq.heappush(heap, (nums[i][0], i, 0))
            curr_max = max(curr_max, nums[i][0])

        best_range = [float("-inf"), float("inf")]

        while heap:
            val, r, c = heapq.heappop(heap)
            if curr_max - val < best_range[1] - best_range[0]:
                best_range = [val, curr_max]
            if c + 1 == len(nums[r]):
                break
            nxt_val = nums[r][c + 1]
            curr_max = max(curr_max, nxt_val)
            heapq.heappush(heap, (nxt_val, r, c + 1))

        return best_range

class Solution {
    struct Element {
        int val, r, c;
        bool operator>(const Element& o) const {
            return val > o.val;
        }
    };
public:
    vector<int> smallestRange(vector<vector<int>>& nums) {
        priority_queue<Element, vector<Element>, greater<Element>> pq;
        int currMax = INT_MIN;
        for (int i = 0; i < (int)nums.size(); i++) {
            pq.push({nums[i][0], i, 0});
            currMax = max(currMax, nums[i][0]);
        }

        int bestMin = -1e6, bestMax = 1e6;

        while (!pq.empty()) {
            auto [val, r, c] = pq.top();
            pq.pop();
            if ((long long)currMax - val < (long long)bestMax - bestMin) {
                bestMin = val;
                bestMax = currMax;
            }
            if (c + 1 == (int)nums[r].size()) break;
            int nxt = nums[r][c + 1];
            currMax = max(currMax, nxt);
            pq.push({nxt, r, c + 1});
        }
        return {bestMin, bestMax};
    }
};

class Solution {
    static class Element implements Comparable<Element> {
        int val, r, c;
        Element(int val, int r, int c) {
            this.val = val;
            this.r = r;
            this.c = c;
        }
        public int compareTo(Element o) {
            return Integer.compare(this.val, o.val);
        }
    }

    public int[] smallestRange(List<List<Integer>> nums) {
        PriorityQueue<Element> pq = new PriorityQueue<>();
        int currMax = Integer.MIN_VALUE;
        for (int i = 0; i < nums.size(); i++) {
            int v = nums.get(i).get(0);
            pq.offer(new Element(v, i, 0));
            currMax = Math.max(currMax, v);
        }

        int bestMin = (int) -1e6, bestMax = (int) 1e6;

        while (!pq.isEmpty()) {
            Element el = pq.poll();
            if ((long) currMax - el.val < (long) bestMax - bestMin) {
                bestMin = el.val;
                bestMax = currMax;
            }
            if (el.c + 1 == nums.get(el.r).size()) break;
            int nxt = nums.get(el.r).get(el.c + 1);
            currMax = Math.max(currMax, nxt);
            pq.offer(new Element(nxt, el.r, el.c + 1));
        }
        return new int[]{bestMin, bestMax};
    }
}

var smallestRange = function(nums) {
    class MinHeap {
        constructor() { this.data = []; }
        push(item) {
            this.data.push(item);
            this._up(this.data.length - 1);
        }
        pop() {
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this._down(0);
            }
            return top;
        }
        size() { return this.data.length; }
        _up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[p].val <= this.data[i].val) break;
                [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
                i = p;
            }
        }
        _down(i) {
            while ((i << 1) + 1 < this.data.length) {
                let left = (i << 1) + 1, right = left + 1;
                let best = (right < this.data.length && this.data[right].val < this.data[left].val) ? right : left;
                if (this.data[i].val <= this.data[best].val) break;
                [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                i = best;
            }
        }
    }

    const pq = new MinHeap();
    let currMax = -Infinity;
    for (let i = 0; i < nums.length; i++) {
        pq.push({ val: nums[i][0], r: i, c: 0 });
        currMax = Math.max(currMax, nums[i][0]);
    }

    let bestMin = -1e6, bestMax = 1e6;

    while (pq.size() > 0) {
        const el = pq.pop();
        if (currMax - el.val < bestMax - bestMin) {
            bestMin = el.val;
            bestMax = currMax;
        }
        if (el.c + 1 === nums[el.r].length) break;
        const nxt = nums[el.r][el.c + 1];
        currMax = Math.max(currMax, nxt);
        pq.push({ val: nxt, r: el.r, c: el.c + 1 });
    }
    return [bestMin, bestMax];
};
